package com.worksphere.service; import com.worksphere.dto.admin.*; import com.worksphere.repository.*; import com.worksphere.entity.DisputeStatus; import org.springframework.stereotype.Service; import java.util.*; @Service public class AdminService {private final UserRepository users;private final JobRepository jobs;private final ApplicationRepository apps;private final CommitmentRepository commitments;private final DisputeRepository disputes;private final RatingRepository ratings;private final StrikeRepository strikes;public AdminService(UserRepository u,JobRepository j,ApplicationRepository a,CommitmentRepository c,DisputeRepository d,RatingRepository r,StrikeRepository s){users=u;jobs=j;apps=a;commitments=c;disputes=d;ratings=r;strikes=s;} public AdminDashboardResponse dashboard(){long workers=users.findAll().stream().filter(u->u.role.name().equals("JOB_SEEKER")).count();long employers=users.findAll().stream().filter(u->u.role.name().equals("EMPLOYER")).count();long open=disputes.findAll().stream().filter(d->d.status!=DisputeStatus.RESOLVED).count();long openJobs=jobs.findAll().stream().filter(j->j.status==com.worksphere.entity.JobStatus.OPEN).count(); long completedJobs=jobs.findAll().stream().filter(j->j.status==com.worksphere.entity.JobStatus.COMPLETED).count(); return new AdminDashboardResponse(users.count(),workers,employers,openJobs,completedJobs,open);} public List<com.worksphere.entity.User> users(){return users.findAllByOrderByCreatedAtDesc();} public List<Map<String,Object>> jobs(){return jobs.findAllByOrderByCreatedAtDesc().stream().map(j->row("id",j.id,"title",j.title,"employerName",j.employer.fullName,"location",j.location,"jobDate",j.jobDate,"status",j.status.name())).toList();} public List<Map<String,Object>> applications(){return apps.findAll().stream().map(a->row("id",a.id,"jobTitle",a.job.title,"workerName",a.worker.fullName,"status",a.status.name(),"appliedAt",a.appliedAt)).toList();} public List<Map<String,Object>> commitments(){return commitments.findAll().stream().map(c->row("id",c.id,"jobTitle",c.job.title,"workerName",c.worker.fullName,"status",c.status.name(),"depositStatus",c.depositStatus.name())).toList();} public List<Map<String,Object>> ratings(){return ratings.findAll().stream().map(r->row("id",r.id,"jobTitle",r.commitment.job.title,"fromUserName",r.fromUser.fullName,"toUserName",r.toUser.fullName,"rating",r.rating,"review",r.review==null?"":r.review)).toList();} public List<Map<String,Object>> strikes(){return strikes.findAllByOrderByCreatedAtDesc().stream().map(x->row("id",x.id,"userName",x.user.fullName,"jobTitle","-","reason",x.reason,"severity",1,"status",x.status.name())).toList();} private Map<String,Object> row(Object... values){Map<String,Object> m=new LinkedHashMap<>();for(int i=0;i<values.length;i+=2)m.put((String)values[i],values[i+1]);return m;} }
